import unittest
from candidate import sum_product

class TestSumProduct(unittest.TestCase):
    def test_normal_case_multiple_numbers(self):
        self.assertEqual(sum_product([1, 2, 3, 4]), (10, 24))

    def test_empty_list(self):
        self.assertEqual(sum_product([]), (0, 1))

    def test_single_element(self):
        self.assertEqual(sum_product([5]), (5, 5))
        self.assertEqual(sum_product([-3]), (-3, -3))

    def test_negative_numbers(self):
        self.assertEqual(sum_product([-1, -2, -3]), (-6, -6))
        self.assertEqual(sum_product([-1, 2, -3]), (-2, 6))

    def test_mixed_numbers(self):
        self.assertEqual(sum_product([1, -2, 3, -4]), (-2, 24))

    def test_all_zeros(self):
        self.assertEqual(sum_product([0, 0, 0]), (0, 0))
        self.assertEqual(sum_product([0]), (0, 0))

    def test_large_numbers(self):
        self.assertEqual(sum_product([1000000, 2000000]), (3000000, 2000000000000))

    def test_floats_when_converted_to_integers(self):
        with self.assertRaises(TypeError):
            sum_product([1.5, 2.5])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            sum_product(None)

    def test_non_list_input(self):
        with self.assertRaises(TypeError):
            sum_product("not a list")

    def test_non_integer_elements(self):
        with self.assertRaises(TypeError):
            sum_product([1, 2, "three"])
        with self.assertRaises(TypeError):
            sum_product([1, 2, 3.5])

    def test_product_with_zero(self):
        self.assertEqual(sum_product([0, 1, 2]), (3, 0))
        self.assertEqual(sum_product([0, 0, 1]), (1, 0))

    def test_product_with_one(self):
        self.assertEqual(sum_product([1, 1, 1]), (3, 1))
        self.assertEqual(sum_product([1, 2, 3]), (6, 6))

    def test_product_with_negative_one(self):
        self.assertEqual(sum_product([-1, 2, -3]), (-2, 6))
        self.assertEqual(sum_product([-1, -1, 2]), (-2, 2))
